#!/usr/bin/env python3
"""Generate the bounded native generic-parent records from checked-in JDK facts.
No Java application or JDK class executes. Facts were extracted independently;
PROVENANCE.json pins their classfile/source verification and tool inputs.
"""
import argparse
import hashlib
import json
import pathlib
import shutil
import subprocess

HERE = pathlib.Path(__file__).resolve().parent

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def generate():
    provenance = json.loads((HERE / 'PROVENANCE.json').read_text())
    facts_path = HERE / 'JDK-GENERIC-PARENT-FACTS.json'
    terminals_path = HERE / 'JDK-RAW-TERMINALS.json'
    if digest(facts_path) != provenance['facts_sha256'] or digest(terminals_path) != provenance['terminal_sha256']:
        raise ValueError('independent JDK fact pin mismatch')
    generic = json.loads(facts_path.read_text())['owners']
    terminals = json.loads(terminals_path.read_text())
    if len(generic) != 8 or len(terminals) != 3:
        raise ValueError('bounded inventory size changed')
    rows = generic + terminals
    owners = {r['owner']: i for i, r in enumerate(rows)}
    if len(owners) != len(rows):
        raise ValueError('duplicate native declaration identity')
    for row in rows:
        parameters = row['parameters']
        for index, parameter in enumerate(parameters):
            if parameter['kind'] != 'parameter' or parameter['owner'] != row['owner'] or parameter['index'] != index:
                raise ValueError('parameter is not owned by actual native declaration')
    q = json.dumps
    lines = ['package transpiler\n', 'import "github.com/NickyBoy89/java2go/symbol"\n',
             '// Code generated by testdata/jdk_generic_parent_origin/generate.py; DO NOT EDIT.\n',
             '// Relative facts and independent JDK evidence are in testdata/jdk_generic_parent_origin/.\n',
             'var jdk21GenericParentCertificates = map[string]string{\n']
    for row in rows:
        lines.append('\t' + q(row['owner']) + ': ' + q(row['class_sha256']) + ',\n')
    lines.append('}\n\nvar jdk21GenericParentRecords = buildJDK21GenericParentRecords()\n\nfunc buildJDK21GenericParentRecords() map[string]jdk21GenericParentRecord {\n')
    for index, row in enumerate(rows):
        for parameter in row['parameters']:
            lines.append(f'\tp{index}_{parameter["index"]} := &symbol.TypeParamDeclaration{{SourceName: {q(parameter["name"])}, GoName: {q(parameter["name"])}}}\n')

    def recipe(record):
        if record['kind'] == 'parameter':
            owner = record['owner']
            index = record['index']
            if owner not in owners or rows[owners[owner]]['parameters'][index] != record:
                raise ValueError('unowned native parameter reference')
            return f'inferredJavaTypeOrigin{{parameter: p{owners[owner]}_{index}, javaType: {q(record["name"])}}}'
        if record['kind'] != 'nominal' or record['owner'] not in owners:
            raise ValueError('uncertified parent declaration recipe')
        arguments = ', '.join(recipe(arg) for arg in record['arguments'])
        return 'inferredJavaTypeOrigin{externalName: ' + q(record['owner']) + ', javaType: ' + q(record['owner']) + (', arguments: []inferredJavaTypeOrigin{' + arguments + '}' if arguments else '') + '}'

    lines.append('\treturn map[string]jdk21GenericParentRecord{\n')
    for index, row in enumerate(rows):
        parameters = ', '.join(f'p{index}_{p["index"]}' for p in row['parameters'])
        parents = ', '.join(recipe(parent) for parent in row['parents'])
        lines.append('\t\t' + q(row['owner']) + ': {certificate: ' + q(row['class_sha256']) + ', parameters: []*symbol.TypeParamDeclaration{' + parameters + '}, parents: []inferredJavaTypeOrigin{' + parents + '}},\n')
    lines.append('\t}\n}\n')
    return ''.join(lines).encode()

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--gofmt', default=shutil.which('gofmt'))
    parser.add_argument('--output', type=pathlib.Path, default=HERE.parents[1] / 'jdk21_generic_parent_origin_data.go')
    args = parser.parse_args()
    if not args.gofmt:
        parser.error('provide --gofmt /path/to/gofmt')
    output = subprocess.run([args.gofmt], input=generate(), capture_output=True, check=True).stdout
    if args.check:
        if args.output.read_bytes() != output:
            raise SystemExit('generated parent data differs')
        print('generated parent data matches checked-in facts')
    else:
        args.output.write_bytes(output)

if __name__ == '__main__':
    main()
